const {chromium}=require('playwright-core');
const assert=require('node:assert/strict');
(async()=>{
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage','--autoplay-policy=no-user-gesture-required']});
 try {
  const context=await browser.newContext({timezoneId:'Europe/Moscow'});
  const page=await context.newPage();const errors=[];
  page.on('pageerror',error=>errors.push(error.message));
  page.on('console',message=>{
   if(message.type()==='error'&&!(message.location().url==='http://localhost:8080/api/auth/session'&&/status of 401/.test(message.text())))errors.push(message.text());
  });
  const feed=await(await context.request.get('http://localhost:8080/api/videos')).json();
  const video=feed.items.find(item=>item.title.endsWith('fb6e2c9a807b'));assert(video);
  for(const [name,url,ready] of [
   ['feed','/',()=>page.locator('.video-card').first().waitFor()],
   ['search','/results?'+new URLSearchParams({q:video.title}),()=>page.getByRole('link',{name:'Смотреть: '+video.title,exact:true}).waitFor()],
   ['watch',video.watch_url,()=>page.locator('.comment-body').first().waitFor()]
  ]) {
   await page.goto('http://localhost:8080'+url);await ready();
   if(name==='watch'){
    await page.locator('video').evaluate(video=>{video.muted=true;return video.play()});
    await page.waitForFunction(()=>document.querySelector('video').currentTime>.3);
    await page.locator('video').evaluate(video=>video.pause());
    assert(await page.getByRole('button',{name:'Нравится',exact:true}).isDisabled());
   }
   for(const width of [390,1440]){
    await page.setViewportSize({width,height:1000});
    assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
    await page.screenshot({path:`/artifacts/final-${name}-${width}.png`,fullPage:true});
   }
   console.log('OK final '+name+' screenshots at 390/1440');
  }
  assert.deepEqual(errors,[]);console.log('OK final browser console, no uncaught exceptions');
 } finally {await browser.close()}
})().catch(error=>{console.error(error.message);process.exitCode=1});

